Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 205;

int N, T;
char gridA[MAXN][MAXN], gridB[MAXN][MAXN];
int cost[MAXN][MAXN];
int route[MAXN][MAXN][MAXN][MAXN];

int dx[4] = {-1,1,0,0};
int dy[4] = {0,0,-1,1};

struct Edge { int u,v,cap,flow; };
int nodeCnt, S, TNode;
int dst[MAXNODE], cur[MAXNODE], que[MAXNODE];
vector<Edge> edges;
vector<int> adj[MAXNODE];

void add_edge(int u,int v,int cap) {
    edges.push_back({u,v,cap,0});
    adj[u].push_back((int)edges.size()-1);
    edges.push_back({v,u,0,0});
    adj[v].push_back((int)edges.size()-1);
}

bool bfs() {
    int h=0,t=0;
    que[t++]=S;
    memset(dst,-1,nodeCnt*sizeof(dst[0]));
    dst[S]=0;
    while (h<t && dst[TNode]==-1) {
        int v=que[h++];
        for(int id: adj[v]) {
            int to=edges[id].v;
            if (dst[to]==-1 && edges[id].flow < edges[id].cap) {
                que[t++]=to;
                dst[to]=dst[v]+1;
            }
        }
    }
    return dst[TNode]!=-1;
}

int dfs(int v,int fl) {
    if (!fl) return 0;
    if (v==TNode) return fl;
    for (int &i=cur[v]; i<(int)adj[v].size(); ++i) {
        int id=adj[v][i];
        int to=edges[id].v;
        if (dst[to]!=dst[v]+1) continue;
        int pushed=dfs(to, min(fl, edges[id].cap-edges[id].flow));
        if (pushed) {
            edges[id].flow += pushed;
            edges[id^1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int dinic() {
    int flow=0;
    while (bfs()) {
        memset(cur,0,nodeCnt*sizeof(cur[0]));
        while (int pushed=dfs(S,INF)) flow += pushed;
    }
    return flow;
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",gridA[i]);
    getchar();
    for(int i=0;i<N;i++) scanf("%s",gridB[i]);

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            cost[i][j]=INF;

    queue<pair<int,int>> q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if (gridA[x][y]=='Z') {
                for(int d=0;d<4;d++)
                    if (x+dx[d]>=0 && x+dx[d]<N && y+dy[d]>=0 && y+dy[d]<N && gridA[x+dx[d]][y+dy[d]]!='Y') {
                        cost[x+dx[d]][y+dy[d]]=1;
                        q.push({x+dx[d], y+dy[d]});
                    }
            }

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop();
        for(int d=0;d<4;d++) {
            int nx=x+dx[d], ny=y+dy[d];
            if (nx>=0 && nx<N && ny>=0 && ny<N && gridA[nx][ny]!='Y' && gridA[nx][ny]!='Z' && cost[nx][ny]==INF) {
                cost[nx][ny]=cost[x][y]+1;
                q.push({nx,ny});
            }
        }
    }

    for(int sx=0; sx<N; ++sx) {
        for(int sy=0; sy<N; ++sy) {
            if (gridA[sx][sy]=='Y' || gridA[sx][sy]=='Z') {
                for(int tx=0; tx<N; ++tx)
                    for(int ty=0; ty<N; ++ty)
                        route[sx][sy][tx][ty]=0;
                continue;
            }
            int dist[MAXN][MAXN];
            for(int i=0;i<N;i++)
                for(int j=0;j<N;j++)
                    dist[i][j]=INF;
            queue<pair<int,int>> q2;
            dist[sx][sy]=0;
            q2.push({sx,sy});
            while(!q2.empty()) {
                int x=q2.front().first, y=q2.front().second;
                q2.pop();
                route[sx][sy][x][y]=1;
                if (dist[x][y] >= T || dist[x][y] >= cost[x][y])
                    continue;
                for(int d=0; d<4; ++d) {
                    int nx=x+dx[d], ny=y+dy[d];
                    if (nx>=0 && nx<N && ny>=0 && ny<N &&
                        gridA[nx][ny]!='Y' && gridA[nx][ny]!='Z' &&
                        dist[nx][ny]==INF &&
                        dist[x][y]+1 <= cost[nx][ny]) {
                        dist[nx][ny]=dist[x][y]+1;
                        q2.push({nx,ny});
                    }
                }
            }
        }
    }

    S=0; TNode=2*N*N+1; nodeCnt=2*N*N+2;

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) {
            if (gridA[i][j]>'0' && gridA[i][j]<='9')
                add_edge(S,1+i*N+j,gridA[i][j]-'0');
            if (gridB[i][j]>'0' && gridB[i][j]<='9')
                add_edge(N*N+1+i*N+j,TNode,gridB[i][j]-'0');
        }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    if (route[x1][y1][x2][y2])
                        add_edge(1+x1*N+y1, N*N+1+x2*N+y2, INF);

    printf("%d\n",dinic());
    return 0;
}
